//! Cargo-driven `msiexec.exe` link, generated by tools/cargo_cell_gen.py
//! from the cmake link it replaces.
//! The body is msiexec-rust; reactos-link builds the PE.

use reactos_link::{Linker, ModuleKind, MsvcrtexKind};
use std::env;

fn main() {
    let arch = env::var("CARGO_CFG_TARGET_ARCH").expect("CARGO_CFG_TARGET_ARCH");
    let (target_json, entry) = match arch.as_str() {
        "x86" => ("i686-pc-windows-gnu", "_WinMainCRTStartup"),
        "x86_64" => ("x86_64-pc-windows-gnu", "WinMainCRTStartup"),
        "aarch64" => ("aarch64-pc-windows-gnullvm", "WinMainCRTStartup"),
        o => panic!("msiexec-cargo: unsupported arch {o}"),
    };

    let late_libs: &[&str] = match arch.as_str() {
        "x86" => &["sdk/lib/uuid/libuuid.a", "sdk/lib/libwine/libwine.a", "sdk/lib/crt/CMakeFiles/oldnames.dir/oldnames.a"],
        "x86_64" => &["sdk/lib/uuid/libuuid.a", "sdk/lib/libwine/libwine.a", "sdk/lib/crt/CMakeFiles/oldnames.dir/oldnames.a"],
        "aarch64" => &["sdk/lib/uuid/libuuid.a", "sdk/lib/libwine/libwine.a", "sdk/lib/crt/CMakeFiles/oldnames.dir/oldnames.a"],
        _ => unreachable!(),
    };

    Linker::new(target_json)
        .rust_staticlib("msiexec-rust")
        .c_from_compile_db("msiexec_shims", &["base/system/msiexec/rust_varargs_shim.c"])
        .resource_from_rc("base/system/msiexec/rsrc.rc", "msiexec_res")
        .import_lib("win32ss/user/user32/user32.spec", "user32.dll", "user32")
        .import_lib("dll/win32/advapi32/advapi32.spec", "advapi32.dll", "advapi32")
        .import_lib("dll/win32/ole32/ole32.spec", "ole32.dll", "ole32")
        .import_lib("dll/win32/comctl32/comctl32.spec", "comctl32.dll", "comctl32")
        .import_lib("dll/win32/msi/msi.spec", "msi.dll", "msi")
        .import_lib("dll/win32/msvcrt/msvcrt.spec", "msvcrt.dll", "msvcrt")
        .import_lib("dll/win32/kernel32/kernel32.spec", "kernel32.dll", "kernel32")
        .import_lib("dll/ntdll/def/ntdll.spec", "ntdll.dll", "ntdll")
        // ...and those cmake linked after the body, in the same order.
        .static_libs_after_body(late_libs)
        .msvcrtex_crt(MsvcrtexKind::ExeAnsi)
        .link(ModuleKind::Win32Exe {
            entry: entry.into(),
            subsystem: "windows:5.01".into(),
        });
}
